public class Main {
    static class Rekening {
        private long saldo;
        void setor(long n) {
            if (n <= 0) throw new IllegalArgumentException("setoran harus positif");
            saldo += n;
        }
        String tarik(long n) {
            if (n > saldo) return "Gagal: saldo tidak cukup";
            saldo -= n;
            return "Berhasil tarik " + n;
        }
        long saldo() { return saldo; }
    }

    public static void main(String[] args) throws Exception {
        Rekening r = new Rekening();
        r.setor(500_000);
        System.out.println(r.tarik(200_000) + ", saldo " + r.saldo());
        System.out.println(r.tarik(900_000) + ", saldo " + r.saldo());
    }
}

