public class Main {
    public static void main(String[] args) throws Exception {
        String rahasia = "kunci-webhook-rahasia";
        String body = "{\"order_id\":\"INV-7\",\"status\":\"settlement\"}";
        Mac mac = Mac.getInstance("HmacSHA256");
        mac.init(new SecretKeySpec(rahasia.getBytes(StandardCharsets.UTF_8), "HmacSHA256"));
        String tanda = HexFormat.of().formatHex(mac.doFinal(body.getBytes(StandardCharsets.UTF_8)));
        System.out.println("Tanda tangan: " + tanda.substring(0, 16) + "...");
        String dariHeader = tanda;
        System.out.println("Valid: " + MessageDigest.isEqual(tanda.getBytes(), dariHeader.getBytes()));
        System.out.println("Body diubah valid? " + MessageDigest.isEqual(tanda.getBytes(), "palsu".getBytes()));
    }
}

import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;

public class Main {
    public static void main(String[] args) throws Exception {
        AtomicInteger atom = new AtomicInteger();
        int[] terkunci = {0};
        Object kunci = new Object();
        List<Thread> ts = new ArrayList<>();
        for (int t = 0; t < 4; t++) {
            Thread th = new Thread(() -> {
                for (int i = 0; i < 10_000; i++) {
                    atom.incrementAndGet();
                    synchronized (kunci) { terkunci[0]++; }
                }
            });
            ts.add(th); th.start();
        }
        for (Thread th : ts) th.join();
        System.out.println("AtomicInteger: " + atom.get() + ", synchronized: " + terkunci[0] + " (harus 40000)");
    }
}

import java.util.*;
