public class Main {
    public static void main(String[] args) throws Exception {
        long mulai = System.currentTimeMillis();
        try (var ex = Executors.newVirtualThreadPerTaskExecutor()) {
            List<Future<Integer>> hasil = new ArrayList<>();
            for (int i = 0; i < 10_000; i++) {
                int id = i;
                hasil.add(ex.submit(() -> { Thread.sleep(100); return id % 2; })); // anggap memanggil API 100 ms
            }
            int total = 0;
            for (var f : hasil) total += f.get();
            long detik = (System.currentTimeMillis() - mulai) / 1000;
            System.out.println("Selesai: " + total + " ganjil, kurang dari 5 detik: " + (detik < 5));
        }
    }
}

public class Main {
