@Entity
@Table(name = "pesanan")
public class Pesanan {
    @Id @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;
    @ManyToOne(fetch = FetchType.LAZY)
    private Pelanggan pelanggan;
