public class Main {
    public static void main(String[] args) throws Exception {
        int[] a = {3, 1, 2, 4, 5, 6};
        int pass = 0;
        boolean tukar = true;
        for (int i = 0; i < a.length - 1 && tukar; i++) {
            tukar = false; pass++;
            for (int j = 0; j < a.length - 1 - i; j++) if (a[j] > a[j + 1]) { int t = a[j]; a[j] = a[j + 1]; a[j + 1] = t; tukar = true; }
        }
        System.out.println(Arrays.toString(a) + " selesai dalam " + pass + " pass (maksimal " + (a.length - 1) + ")");
    }
}

