cx.code:
SELECT nama FROM pelanggan pl
WHERE EXISTS (
  SELECT 1 FROM pesanan p JOIN detail d ON d.pesanan_id = p.id
  JOIN produk pr ON pr.id = d.produk_id
  WHERE p.pelanggan_id = pl.id AND pr.kategori = 'Alat'
);

