WITH penjualan AS (
  SELECT pr.kategori, d.qty * d.harga AS nilai
  FROM detail d JOIN produk pr ON pr.id = d.produk_id
  JOIN pesanan p ON p.id = d.pesanan_id AND p.status <> 'batal'
), per_kategori AS (
  SELECT kategori, SUM(nilai) AS omzet FROM penjualan GROUP BY kategori
)
SELECT kategori, omzet, ROUND(100.0 * omzet / (SELECT SUM(omzet) FROM per_kategori), 1) AS persen
FROM per_kategori ORDER BY omzet DESC;

