CREATE TABLE buku (id INTEGER PRIMARY KEY, judul TEXT);
CREATE TABLE penulis (id INTEGER PRIMARY KEY, nama TEXT);
CREATE TABLE buku_penulis (buku_id INTEGER, penulis_id INTEGER, PRIMARY KEY (buku_id, penulis_id));
INSERT INTO buku VALUES (1, 'Laut Bercerita'), (2, 'Belajar SQL Bersama');
INSERT INTO penulis VALUES (1, 'Leila'), (2, 'Andi'), (3, 'Rina');
INSERT INTO buku_penulis VALUES (1, 1), (2, 2), (2, 3);
SELECT b.judul, GROUP_CONCAT(p.nama, ', ') AS penulis
FROM buku b JOIN buku_penulis bp ON bp.buku_id = b.id JOIN penulis p ON p.id = bp.penulis_id
GROUP BY b.id;
